function readU16(v,o){return v.getUint16(o,true)}function readU32(v,o){return v.getUint32(o,true)}
async function inflateRaw(bytes){if(!("DecompressionStream" in window))throw new Error("Ваш браузер не підтримує локальне розпакування DOCX. Використайте актуальний Chrome/Edge або збережіть матеріал як TXT/HTML.");const ds=new DecompressionStream("deflate-raw"),stream=new Blob([bytes]).stream().pipeThrough(ds);return new Uint8Array(await new Response(stream).arrayBuffer())}
