async function parseDocx(file){const zip=await openZip(await file.arrayBuffer()),xmlBytes=await zip.extract("word/document.xml");if(!xmlBytes)throw new Error("word/document.xml not found");const parser=new DOMParser(),W="http://schemas.openxmlformats.org/wordprocessingml/2006/main",A="http://schemas.openxmlformats.org/drawingml/2006/main",R="http://schemas.openxmlformats.org/officeDocument/2006/relationships";let relMap={};const relBytes=await zip.extract("word/_rels/document.xml.rels");if(relBytes){const relDoc=parser.parseFromString(new TextDecoder().decode(relBytes),"application/xml");[...relDoc.getElementsByTagName("Relationship")].forEach(x=>relMap[x.getAttribute("Id")]=x.getAttribute("Target"))}
const doc=parser.parseFromString(new TextDecoder().decode(xmlBytes),"application/xml"),paragraphs=[],imageRefs=[];for(const p of [...doc.getElementsByTagNameNS(W,"p")]){const text=[...p.getElementsByTagNameNS(W,"t")].map(x=>x.textContent).join("").trim();const ps=p.getElementsByTagNameNS(W,"pStyle")[0],style=ps?(ps.getAttributeNS(W,"val")||ps.getAttribute("w:val")||""):"";if(text)paragraphs.push({text,heading:/heading|заголов/i.test(style)});for(const b of [...p.getElementsByTagNameNS(A,"blip")]){const id=b.getAttributeNS(R,"embed")||b.getAttribute("r:embed");if(id&&relMap[id])imageRefs.push(relMap[id])}}
const images=[];for(const target of [...new Set(imageRefs)]){const path=target.startsWith("/")?target.slice(1):"word/"+target.replace(/^\.\//,"");const bytes=await zip.extract(path);if(!bytes)continue;const mime=mimeForPath(path);if(!["image/jpeg","image/png","image/webp"].includes(mime))continue;const data=await dataUrlFromBytes(bytes,mime),meta=await imageMeta(data);images.push({src:data,name:path.split("/").pop(),...meta})}return {paragraphs,images}}
function rtfToText(s){return s.replace(/\\par[d]?/gi,"\n\n").replace(/\\'[0-9a-f]{2}/gi,"").replace(/\\[a-z]+-?\d* ?/gi,"").replace(/[{}]/g,"").replace(/\n{3,}/g,"\n\n").trim()}
function paragraphsFromText(s){return s.replace(/\r/g,"").split(/\n\s*\n/).map(x=>x.replace(/\n+/g," ").trim()).filter(Boolean).map(text=>({text,heading:false}))}
async function parseArticleFile(file){const ext=(file.name.split(".").pop()||"").toLowerCase();if(ext==="docx")return await parseDocx(file);const raw=await file.text();if(ext==="html"||ext==="htm"){const d=new DOMParser().parseFromString(raw,"text/html"),paragraphs=[...d.querySelectorAll("h1,h2,h3,p,li")].map(x=>({text:x.textContent.trim(),heading:/^H[1-3]$/.test(x.tagName)})).filter(x=>x.text),images=[];for(const im of [...d.querySelectorAll("img")]){const src=im.getAttribute("src")||"";if(/^data:image\/(?:jpeg|png|webp)/.test(src)||/^https:\/\//.test(src)){const meta=await imageMeta(src);images.push({src,name:im.getAttribute("alt")||"HTML image",...meta})}}return {paragraphs,images}}if(ext==="rtf")return {paragraphs:paragraphsFromText(rtfToText(raw)),images:[]};return {paragraphs:paragraphsFromText(raw.replace(/^#{1,6}\s+/gm,"")),images:[]}}
function articleBlockCost(b){if(b.type==="image")return b.qualityOk?32:999;const n=(b.text||"").length;return Math.max(7,Math.ceil(n/90)*5)+(b.heading?4:0)}
function paginateArticleMaterial(meta){const raw=meta.paragraphs.map(x=>({type:"text",...x}));const images=meta.images.filter(x=>x.qualityOk);if(images.length){const step=Math.max(1,Math.floor(raw.length/(images.length+1)));images.forEach((im,i)=>raw.splice(Math.min(raw.length,(i+1)*step+i),0,{type:"image",...im}))}const pages=[];let blocks=[],used=meta.lead?22:16;for(const b of raw){const cost=articleBlockCost(b);if(blocks.length&&used+cost>ARTICLE_PAGE_CAPACITY){pages.push(blocks);blocks=[];used=12}blocks.push(b);used+=cost}if(blocks.length||!pages.length)pages.push(blocks);return pages}
function articlePageMarkup(p){const d=p.design||{},part=d.part||1,total=d.totalParts||1;return '<div class="articlepage2"><div class="articlepagehead"><span>IIG INDUSTRY INTELLIGENCE · '+String(p.pageNumber||"").padStart(2,"0")+'</span><b>'+esc(d.typeLabel||"IIG ORIGINAL")+'</b></div><h2>'+esc(d.title)+(total>1&&part>1?' — ПРОДОВЖЕННЯ':"")+'</h2>'+(part===1&&d.lead?'<p class="articlelead">'+esc(d.lead)+'</p>':"")+'<div class="articleblocks">'+(d.blocks||[]).map(b=>b.type==="image"?'<figure><img src="'+esc(b.src)+'" alt="'+esc(b.name||"Фото матеріалу")+'"><figcaption>'+esc(b.name||"")+'</figcaption></figure>':(b.heading?'<h3>'+esc(b.text)+'</h3>':'<p>'+esc(b.text)+'</p>')).join("")+'</div><div class="articlepagefoot"><span>IIG Monthly Digest · '+esc(MONTHS_UA[digestIssue.month-1][0]+MONTHS_UA[digestIssue.month-1].slice(1).toLowerCase())+' '+digestIssue.year+' · '+part+'/'+total+'</span><a href="forms.html#subscribe">ПІДПИСАТИСЯ НА ДАЙДЖЕСТ</a></div></div>'}
function clearArticleImport(){pendingArticleImport={fileName:"",title:"",lead:"",paragraphs:[],images:[]};$("articleSourceFile").value="";$("articleImportTitle").value="";$("articleImportLead").value="";$("articleImportBody").value="";$("articleImportUrl").value="";$("articleImageCount").textContent="0";$("articleImportStatus").className="miniwarn";$("articleImportStatus").textContent="DOCX/TXT/MD/RTF/HTML. DOCX читається локально в браузері; текст і вбудовані фото не передаються зовнішнім сервісам."}
async function importArticleSource(file){if(!file)return;const status=$("articleImportStatus");status.className="miniwarn";status.textContent="Читання "+file.name+"…";try{const parsed=await parseArticleFile(file),ps=parsed.paragraphs||[];const firstHeading=ps.find(x=>x.heading)||ps[0];const title=firstHeading?firstHeading.text.replace(/^#{1,6}\s*/,""):"";const body=ps.filter(x=>x!==firstHeading).map(x=>x.text).join("\n\n");pendingArticleImport={fileName:file.name,title,lead:"",paragraphs:ps.filter(x=>x!==firstHeading),images:parsed.images||[]};$("articleImportTitle").value=title;$("articleImportBody").value=body;$("articleImageCount").textContent=String(pendingArticleImport.images.length);const low=pendingArticleImport.images.filter(x=>!x.qualityOk).length;status.className="miniwarn "+(low?"warn":"ok");status.textContent="Імпортовано: "+pendingArticleImport.paragraphs.length+" абзаців · "+pendingArticleImport.images.length+" фото"+(low?" · "+low+" фото нижче мінімуму "+ARTICLE_IMAGE_MIN_LONG_SIDE+" px і не підуть у верстку":"")+". Матеріал можна відредагувати перед формуванням сторінок."}catch(e){status.className="miniwarn error";status.textContent="ПОМИЛКА ІМПОРТУ: "+e.message}}
function buildImportedArticlePages(previewOnly=false){const title=$("articleImportTitle").value.trim(),lead=$("articleImportLead").value.trim(),body=$("articleImportBody").value.trim(),url=$("articleImportUrl").value.trim(),type=$("articleMaterialType").value;if(!title||!body)return gate("Матеріал потребує заголовок і текст.");if(url&&!validInternalOrHttps(url))return gate("Пряме посилання має бути HTTPS або конкретним внутрішнім IIG route.");const paragraphs=paragraphsFromText(body),meta={title,lead,paragraphs,images:pendingArticleImport.images||[]},parts=paginateArticleMaterial(meta),labels={IIG_ORIGINAL:"IIG ORIGINAL",SUCCESS_PROJECT:"УСПІШНИЙ ПРОЄКТ IIG",PARTNER:"PARTNER MATERIAL",SPONSORED:"SPONSORED MATERIAL"};const built=parts.map((blocks,i)=>({name:"Імпортована стаття — "+title+(parts.length>1?" "+(i+1)+"/"+parts.length:""),kind:"article",capacity:ARTICLE_PAGE_CAPACITY,items:[],design:{type,typeLabel:labels[type],title,lead,blocks,part:i+1,totalParts:parts.length,sourceUrl:url,sourceFile:pendingArticleImport.fileName}}));if(previewOnly){mt.innerHTML='<div class="previewbox">'+built.map((p,i)=>articlePageMarkup({...p,pageNumber:i+4})).join("")+'</div>';modal.classList.add("show");return}digestPages.push(...built);renderDigest();auditEvent("Імпортовано матеріал у канву Page 2",pendingArticleImport.fileName||title,built.length+" сторінок");gate("Матеріал автоматично зверстано на "+built.length+" сторінок. Footer і CTA підписки збережені на кожній сторінці.")}


function syncApprovalUI(){const n=selected&&effective(selected);const ok=n&&n.status==="APPROVED"&&n.admin_approved;const s=$("approvalState"),b=$("approveDemo");if(s){s.className="approvalstate "+(ok?"approved":"pending");s.textContent=ok?"● ЗАТВЕРДЖЕНО ДО ПУБЛІКАЦІЇ":"● НЕ ЗАТВЕРДЖЕНО ДО ПУБЛІКАЦІЇ"}if(b)b.textContent=ok?"✓ ЗАТВЕРДЖЕНО ДО ПУБЛІКАЦІЇ":"✓ Затвердити до публікації"}
