function renderNews(){const q=($("newsSearch").value||"").toLowerCase(),filter=$("newsFilter").value,type=$("contentTypeFilter")?$("contentTypeFilter").value:"all",rub=$("digestRubricFilter")?$("digestRubricFilter").value:"all";const arr=items.map(effective).filter(n=>(filter==="all"||n.status===filter)&&(type==="all"||n.content_type===type)&&(rub==="all"||digestRubric(n)===rub)&&((titleOf(n)+" "+n.slug+" "+sectorUA(n.sector||n.topic||"other")).toLowerCase().includes(q)));if(!arr.length){$("newsList").innerHTML='<div class="empty">Нічого не знайдено. Змініть фільтр або створіть матеріал.</div>';return}const order=["GENERAL","FINANCE","REGULATION","ADVICE"];$("newsList").innerHTML=order.map(r=>{const group=arr.filter(n=>digestRubric(n)===r);if(!group.length)return "";return '<div class="rubrichead">'+RUBRIC_LABEL[r]+' <span>'+group.length+'</span></div>'+group.map(n=>{const ok=n.status==="APPROVED"&&n.admin_approved;return '<div class="newsitem '+(selected&&selected.slug===n.slug?"selected":"")+'" data-slug="'+esc(n.slug)+'"><b>'+esc(titleOf(n))+'</b><div class="newsmeta"><span class="typebadge">'+esc(TYPE[n.content_type])+'</span><span>'+esc(sectorUA(n.sector||n.topic||"other"))+'</span><span class="'+(ok?"publicationapproved":"pill blue")+'">'+(ok?"ЗАТВЕРДЖЕНО ДО ПУБЛІКАЦІЇ":esc(statusUA(n.status)))+'</span></div></div>'}).join("")}).join("");document.querySelectorAll("#newsList .newsitem").forEach(x=>x.onclick=()=>selectItem(x.dataset.slug))}
function selectItem(slug){selected=effective(items.find(n=>n.slug===slug));if(!selected)return;$("editorEmpty").classList.add("hidden");$("newsEditor").classList.remove("hidden");$("edTitle").value=titleOf(selected);$("edSector").value=["energy","metallurgy","food","logistics","datacenters","chemical","agriculture","pharma","waste","finance","regulation","other"].includes(selected.sector)?selected.sector:"other";if($("edDigestRubric"))$("edDigestRubric").value=selected.content_type==="ADVICE"?"ADVICE":(["GENERAL","FINANCE","REGULATION"].includes(selected.digest_rubric)?selected.digest_rubric:"AUTO");if($("edBodyHint"))$("edBodyHint").textContent=selected.content_type==="ADVICE"?"Для ADVICE: кожен блок — перший рядок заголовок секції, далі текст; блоки розділяються порожнім рядком.":"Для NEWS — основний текст матеріалу.";$("edDate").value=selected.publication_date||"";$("edSummary").value=summaryOf(selected);$("edBody").value=bodyOf(selected);$("edSource").value=selected.canonical_url||"";$("edSlug").value=selected.slug||"";renderNews();syncApprovalUI()}
function parseAdviceSections(text,old=[]){const blocks=String(text||"").trim().split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean);return blocks.map((b,i)=>{const lines=b.split("\n"),heading=(lines.shift()||("Розділ "+(i+1))).trim(),body=lines.join("\n").trim();return {heading:{...((old[i]||{}).heading||{}),ua:heading},body:{...((old[i]||{}).body||{}),ua:body}}})}
