function renderLibrary(){const q=($("digestSearch").value||"").toLowerCase();const arr=approved().filter(n=>(titleOf(n)+" "+n.slug+" "+sectorUA(n.sector||n.topic||"other")).toLowerCase().includes(q));const order=["GENERAL","FINANCE","REGULATION","ADVICE"];$("digestLibrary").innerHTML=order.map(r=>{const group=arr.filter(n=>digestRubric(n)===r);if(!group.length)return "";return '<div class="rubrichead">'+RUBRIC_LABEL[r]+' <span>'+group.length+'</span></div>'+group.map(n=>'<div class="newsitem"><b>'+esc(titleOf(n))+'</b><div class="newsmeta"><span>'+esc(sectorUA(n.sector||n.topic||"other"))+'</span><span class="publicationapproved">ЗАТВЕРДЖЕНО</span>'+(r==="ADVICE"?'':'<button class="btn primary addDigest" data-slug="'+esc(n.slug)+'">+ До дайджесту</button>')+'</div></div>').join("")}).join("")||'<div class="empty">Немає затверджених матеріалів. Спочатку затвердьте матеріал у розділі «Новини та публікації».</div>';document.querySelectorAll(".addDigest").forEach(b=>b.onclick=()=>addToDigest(b.dataset.slug))}
