function fixedAdvice(){return approved().filter(n=>digestRubric(n)==="ADVICE").slice(0,3)}
function autoFillDigest(showMessage=true){const extras=digestPages.filter(p=>p.kind==="promo"||p.kind==="article");digestPages=digestPages.filter((p,i)=>i<3);digestPages.forEach(p=>p.items=[]);const pool=approved().filter(n=>digestRubric(n)!=="ADVICE").map(makeDigestItem);const priority=[...pool.filter(x=>x.rubric==="GENERAL"),...pool.filter(x=>x.rubric==="FINANCE"),...pool.filter(x=>x.rubric==="REGULATION")];priority.forEach(placePacked);digestPages.push(...extras);auditEvent("Автозаповнення дайджесту",priority.length+" матеріалів","PACKED");renderDigest();if(showMessage)gate("Автозаповнення завершено: Page 3 заповнюється рубриками «Фінанси» та «Законодавство / Регулювання», після чого решта матеріалів переноситься на наступні сторінки без переповнення.")}
