function renderDigest(){let count=0;const advice=fixedAdvice();$("digestPages").innerHTML=digestPages.map((p,pi)=>{count+=p.items.length;const cover=p.kind==="cover"?coverMarkup(p.design||coverDraft):"";const list=p.items.length?p.items.map((it,ii)=>'<div class="digestitem"><span class="order">'+(ii+1)+'</span><span><b>'+esc(it.title)+'</b><br><small>'+esc(RUBRIC_LABEL[it.rubric]||TYPE[it.type])+' · вага '+slotCost(it).toFixed(2)+' · '+esc(it.url)+'</small></span><span><button class="iconbtn upItem" data-p="'+pi+'" data-i="'+ii+'">↑</button> <button class="iconbtn downItem" data-p="'+pi+'" data-i="'+ii+'">↓</button> <button class="iconbtn moveItem" data-p="'+pi+'" data-i="'+ii+'">⇄</button> <button class="iconbtn delItem" data-p="'+pi+'" data-i="'+ii+'">×</button></span></div>').join(""):(p.kind==="cover"?"":'<div class="empty smartempty">На цій сторінці ще є вільне місце. Додайте затверджені матеріали або натисніть «Автозаповнити по вільному місцю».</div>');const adv=p.kind==="finance"?'<div class="fixedadvice"><b>ПОРАДИ ГОЛОВНОГО ІНЖЕНЕРА · ФІКСОВАНИЙ РОЗМІР 3 СЛОТИ</b>'+(advice.length?advice.map(a=>'<div>• '+esc(titleOf(a))+'</div>').join(""):'<small>Немає затверджених порад.</small>')+'</div>':"";const promo=p.kind==="promo"?extraPageMarkup(p):"",article=p.kind==="article"?articlePageMarkup({...p,pageNumber:pi+1}):"";return '<div class="digestpage" data-kind="'+p.kind+'"><div class="digestpagehead"><div><b>'+esc(p.name)+'</b><div>'+pageStatus(p)+'</div></div><span><button class="iconbtn renamePage" data-p="'+pi+'">✎</button> '+(pi>2?'<button class="iconbtn delPage" data-p="'+pi+'">×</button>':"")+'</span></div><div class="digestpagebody">'+cover+(p.kind==="promo"?promo:p.kind==="article"?article:list)+adv+'</div>'+(p.kind==="promo"?'<div class="toolbar"><button class="btn primary editPromo" data-p="'+pi+'">Редагувати сторінку</button></div>':"")+'</div>'}).join("");$("digestCounter").textContent=count+" матеріалів + "+advice.length+" поради";const totalFree=digestPages.filter(p=>p.kind!=="cover").reduce((s,p)=>s+pageFree(p),0);if($("digestPackingStatus"))$("digestPackingStatus").textContent="Вільний ресурс: "+totalFree.toFixed(1)+" умовних слотів";document.querySelectorAll(".delItem").forEach(b=>b.onclick=()=>{digestPages[+b.dataset.p].items.splice(+b.dataset.i,1);compactDigest();renderDigest()});document.querySelectorAll(".upItem").forEach(b=>b.onclick=()=>moveWithin(+b.dataset.p,+b.dataset.i,-1));document.querySelectorAll(".downItem").forEach(b=>b.onclick=()=>moveWithin(+b.dataset.p,+b.dataset.i,1));document.querySelectorAll(".moveItem").forEach(b=>b.onclick=()=>movePage(+b.dataset.p,+b.dataset.i));document.querySelectorAll(".delPage").forEach(b=>b.onclick=()=>{digestPages.splice(+b.dataset.p,1);compactDigest();renderDigest()});document.querySelectorAll(".renamePage").forEach(b=>b.onclick=()=>{const i=+b.dataset.p,n=prompt("Назва сторінки",digestPages[i].name);if(n){digestPages[i].name=n;renderDigest()}});document.querySelectorAll(".editPromo").forEach(b=>b.onclick=()=>openExtraEditor(+b.dataset.p))}
function compactDigest(){const extras=digestPages.filter(p=>p.kind==="promo"||p.kind==="article");const all=digestPages.filter(p=>p.kind!=="promo"&&p.kind!=="article").flatMap(p=>p.items);digestPages=digestPages.filter((p,i)=>i<3);digestPages.forEach(p=>p.items=[]);all.forEach(placePacked);digestPages.push(...extras)}
function moveWithin(p,i,d){const a=digestPages[p].items,jj=i+d;if(jj<0||jj>=a.length)return;[a[i],a[jj]]=[a[jj],a[i]];renderDigest()}
function movePage(p,i){const item=digestPages[p].items[i];const t=Number(prompt("Перемістити на сторінку № (1-"+digestPages.length+")",String(Math.min(p+2,digestPages.length))))-1;if(!Number.isInteger(t)||t<0||t>=digestPages.length||t===p)return;if(!pageFits(digestPages[t],item))return gate("На вибраній сторінці недостатньо місця або рубрика несумісна з макетом. Система не допускає переповнення.");digestPages[t].items.push(digestPages[p].items.splice(i,1)[0]);renderDigest()}
