$("changeDigestIssue").onclick=()=>{const m=Number(prompt("Місяць (1-12)",String(digestIssue.month))),y=Number(prompt("Рік",String(digestIssue.year)));if(!Number.isInteger(m)||m<1||m>12||!Number.isInteger(y)||y<2020||y>2100)return gate("Некоректний місяць або рік.");digestIssue={month:m,year:y};updateIssueUI();renderDigest();auditEvent("Змінено місяць/рік Digest",MONTHS_UA[m-1]+" "+y)};
$("addDigestPage").onclick=()=>{const n=digestPages.length+1;digestPages.push({name:"Сторінка "+n+" — Додатковий матеріал",kind:"promo",capacity:0,items:[],design:{type:"IIG_ORIGINAL",title:"Нова сторінка "+n,subtitle:"",body:"",cta1:"Детальніше",cta1Url:"",cta2:"Розмістити проєкт",cta2Url:"forms.html#project",announcements:[],overlay:0.55,bgPosition:"center",bgData:"",bgName:"",width:0,height:0}});renderDigest();openExtraEditor(digestPages.length-1);auditEvent("Додано сторінку 4+",String(n),"DRAFT")};
