$("saveExtraPage").onclick=()=>{const x=collectExtraPage(),p=digestPages[x.i];if(!p||p.kind!=="promo")return;if(!x.design.title||!x.design.body)return gate("Додаткова сторінка потребує заголовок і основний текст.");if(!validInternalOrHttps(x.design.cta1Url)||!validInternalOrHttps(x.design.cta2Url))return gate("CTA має вести на HTTPS або конкретний внутрішній IIG route.");p.design=x.design;p.name="Сторінка "+(x.i+1)+" — "+({IIG_ORIGINAL:"IIG ORIGINAL",SUCCESS_PROJECT:"Успішний проєкт",PARTNER:"Partner",SPONSORED:"Sponsored",EDITORIAL:"Редакційна"}[x.design.type]||"Матеріал");pendingExtraBg=null;renderDigest();auditEvent("Збережено додаткову сторінку",p.name,"DRAFT")};
