$("previewDigest").onclick=()=>{const advice=fixedAdvice();mt.innerHTML='<div class="previewbox"><span class="issuebadge">'+MONTHS_UA[digestIssue.month-1]+' '+digestIssue.year+'</span><h1>IIG Monthly Digest — попередній перегляд</h1>'+digestPages.map((p,i)=>'<div class="previewpage"><h3>'+(i+1)+'. '+esc(p.name)+'</h3><div>'+pageStatus(p)+'</div><ol>'+p.items.map(x=>'<li>'+esc(x.title)+'<br><small>'+esc(RUBRIC_LABEL[x.rubric])+' · '+esc(x.url)+'</small></li>').join("")+'</ol>'+(p.kind==="finance"?'<div class="fixedadvice"><b>ПОРАДИ ГОЛОВНОГО ІНЖЕНЕРА</b>'+advice.map(a=>'<div>• '+esc(titleOf(a))+'</div>').join("")+'</div>':"")+'</div>').join("")+'</div>';modal.classList.add("show");auditEvent("Попередній перегляд","Digest")};
$("approveDigestProd").onclick=()=>{const all=digestPages.flatMap(p=>p.items),bad=all.filter(x=>!x.url||!x.slug),overflow=digestPages.filter(p=>["news","finance"].includes(p.kind)&&pageUsed(p)>p.capacity+.001),badArticle=digestPages.filter(p=>p.kind==="article").filter(p=>!p.design||!p.design.title||!(p.design.blocks||[]).length||!p.design.typeLabel||!validInternalOrHttps(p.design.sourceUrl)),badPromo=digestPages.filter(p=>p.kind==="promo").filter(p=>!p.design||!p.design.title||!p.design.body||!validInternalOrHttps(p.design.cta1Url)||!validInternalOrHttps(p.design.cta2Url)||(["PARTNER","SPONSORED"].includes(p.design.type)&&!p.design.type));if(!all.length)return gate("Дайджест порожній — схвалення заблоковано.");if(bad.length)return gate("DIGEST_RELEASE_BLOCKED: є матеріали без конкретного IIG URL.");if(overflow.length)return gate("DIGEST_RELEASE_BLOCKED: є переповнені сторінки.");if(badArticle.length)return gate("DIGEST_RELEASE_BLOCKED: імпортована стаття має порожню сторінку, відсутній тип/заголовок або некоректне пряме посилання.");if(badPromo.length)return gate("DIGEST_RELEASE_BLOCKED: додаткова сторінка 4+ не заповнена або має некоректний CTA URL.");auditEvent("Спроба схвалення Digest","exact SHA","BLOCKED STEP27");gate("Структура, місткість сторінок та прямі IIG URL пройшли Demo QA. Фіксація exact PDF SHA і production approval виконуються через захищений backend на КРОЦІ 27.")};


function renderReleaseReadiness(){if(!$("releaseReadiness"))return;const arr=[...new Map(items.map(n=>[n.slug,effective(n)])).values()],ok=arr.filter(n=>n.status==="APPROVED"&&n.admin_approved),counts={general:ok.filter(n=>digestRubric(n)==="GENERAL").length,finance:ok.filter(n=>digestRubric(n)==="FINANCE").length,regulation:ok.filter(n=>digestRubric(n)==="REGULATION").length,advice:ok.filter(n=>digestRubric(n)==="ADVICE").length,draft:arr.filter(n=>["DRAFT","REVIEW"].includes(n.status)).length,badlink:ok.filter(n=>n.content_type!=="ADVICE"&&!n.slug).length};const checks=[["Україна / Світ",counts.general,counts.general>=1],["Фінанси",counts.finance,counts.finance>=1],["Законодавство / Регулювання",counts.regulation,counts.regulation>=1],["Поради Головного інженера",counts.advice,counts.advice>=3],["Чернетки / На перевірці",counts.draft,counts.draft===0],["Матеріали без direct ID",counts.badlink,counts.badlink===0]];$("releaseReadiness").innerHTML=checks.map(x=>'<div class="readinessitem"><span>'+esc(x[0])+'</span><b>'+x[1]+'</b><span class="pill '+(x[2]?"green":"amber")+'">'+(x[2]?"OK":"УВАГА")+'</span></div>').join("");const ready=checks.every(x=>x[2]);$("releaseReadinessState").className="pill "+(ready?"green":"amber");$("releaseReadinessState").textContent=ready?"READY FOR DIGEST":"ПОТРІБНА МОДЕРАЦІЯ"}
