let sourceRegistry=[];
function renderSourceRegistry(){const p=$("sourceRegistryPreview");if(!p)return;const q=($("sourceSearch")?.value||"").toLowerCase(),f=$("sourceStateFilter")?.value||"all",arr=sourceRegistry.filter(x=>(f==="all"||(f==="verified"?x.technical_url_verified:!x.technical_url_verified))&&((x.name+" "+x.country+" "+x.category+" "+x.website_url).toLowerCase().includes(q)));p.innerHTML='<table class="table"><thead><tr><th>ID</th><th>Джерело</th><th>Пріоритет</th><th>URL</th><th>Feed</th></tr></thead><tbody>'+arr.slice(0,50).map(x=>'<tr><td>'+esc(x.id)+'</td><td>'+esc(x.name)+'</td><td>'+esc(x.priority)+'</td><td>'+(x.technical_url_verified?'<span class="pill green">VERIFIED</span>':'<span class="pill amber">CHECK</span>')+'</td><td>'+(x.feed_verified?'<span class="pill green">VERIFIED</span>':'<span class="pill amber">'+esc(x.adapter_type||"UNCONFIGURED")+'</span>')+'</td></tr>').join("")+'</tbody></table><div class="muted">Показано '+Math.min(50,arr.length)+' із '+arr.length+' за поточним фільтром.</div>'}
async function loadSources(){try{const d=await json("content/discovery/IIG_news_source_registry_260.json"),arr=Array.isArray(d)?d:(d.sources||[]);sourceRegistry=arr;$("sourceCount").textContent=arr.length;$("sourceCount2").textContent=arr.length;const verified=arr.filter(x=>x.technical_url_verified).length,feeds=arr.filter(x=>x.feed_verified).length;if($("sourceHealthSummary"))$("sourceHealthSummary").innerHTML='<b>Технічний стан:</b> URL verified '+verified+'/'+arr.length+' · Feed verified '+feeds+'/'+arr.length+'. Неперевірене джерело не вважається production-ready лише через owner_approved.';renderSourceRegistry()}catch(e){$("sourceCount").textContent="ПОМИЛКА";$("sourceCount2").textContent="ПОМИЛКА"}}
if($("sourceSearch"))$("sourceSearch").oninput=renderSourceRegistry;if($("sourceStateFilter"))$("sourceStateFilter").onchange=renderSourceRegistry;
async function loadContent(manual=false){try{const n=await json("content/public-news.json"),a=await json("content/public-advice.json");const news=(Array.isArray(n)?n:(n.items||n.news||[])).map(x=>({...x,content_type:"NEWS"}));const advice=(Array.isArray(a)?a:(a.items||[])).map(x=>({...x,content_type:"ADVICE",sector:"other",status:x.status||"APPROVED",admin_approved:x.admin_approved!==false}));items=[...news,...advice];restoreEditorial();$("newsCount").textContent=items.length;renderNews();renderLibrary();updateIssueUI();syncCoverInputs();autoFillDigest(false);renderReleaseReadiness();if(manual)gate("Дані з main оновлено. Локальні редакційні чернетки збережено та накладено поверх базового реєстру.")}catch(e){$("newsCount").textContent="ПОМИЛКА";$("newsList").innerHTML='<div class="empty">Помилка завантаження контенту.</div>'}}
const demoRequests={project:[{id:"PRJ-001",name:"Demo Applicant",company:"Demo Industrial LLC",email:"project.demo@example.com",phone:"+380 00 000 0000",industry:"Metallurgy & Heavy",solution:"CHP / Cogeneration",message:"6–8 MW on-site generation, FEED stage",consent:"Contact data processing for project response",status:"REVIEW"}],subscribe:[{id:"SUB-001",name:"Digest Demo",company:"Demo Energy",email:"digest.demo@example.com",language:"UA",consent:"IIG Monthly Digest consent",marketingConsent:true,status:"REVIEW"},{id:"SUB-002",name:"Opt-out Demo",company:"Demo Former Subscriber",email:"unsubscribe.demo@example.com",language:"UA",consent:"UNSUBSCRIBE",unsubscribe:true,status:"SUPPRESSED"}],engineer:[{id:"ENG-001",name:"Engineer Demo",company:"Demo Plant",email:"engineer.demo@example.com",position:"Chief Power Engineer",message:"Grid connection and BESS integration question",consent:"Contact data processing for response",status:"REVIEW"}]};
function field(k,v){return '<div><small>'+esc(k)+'</small><b>'+esc(v||"—")+'</b></div>'}
function reqCard(r,type){const red=r.unsubscribe===true||r.status==="SUPPRESSED";return '<div class="requestcard '+(red?"unsubscribed":"")+'" data-rid="'+esc(r.id)+'"><h3>'+esc(r.id)+' · '+esc(r.company||r.name)+'</h3><div class="requestfields">'+field("Ім’я",r.name)+field("Компанія",r.company)+field("Email",r.email)+field("Телефон / Посада",r.phone||r.position)+field("Напрям / Мова",r.industry||r.language||type)+field("Запит",r.message||r.solution||"Підписка на Digest")+field("Згода",r.consent)+field("Статус",red?"ВІДПИСАНО / SUPPRESSED":"НА МОДЕРАЦІЇ")+'</div><div class="toolbar">'+(red?'<span class="unsub-text">● ВІДПИСАНО — РОЗСИЛКА ЗАБОРОНЕНА</span>':'<button class="btn success reqAccept" data-kind="'+type+'" data-id="'+esc(r.id)+'">✓ Схвалити та додати до бази</button><button class="btn danger reqReject" data-kind="'+type+'" data-id="'+esc(r.id)+'">Відхилити</button>')+'</div></div>'}
function renderRequests(){if($("projectRequests"))$("projectRequests").innerHTML=demoRequests.project.map(r=>reqCard(r,"project")).join("");if($("subscribeRequests"))$("subscribeRequests").innerHTML=demoRequests.subscribe.map(r=>reqCard(r,"subscribe")).join("");if($("engineerRequests"))$("engineerRequests").innerHTML=demoRequests.engineer.map(r=>reqCard(r,"engineer")).join("");document.querySelectorAll(".reqAccept").forEach(b=>b.onclick=()=>moderateRequest(b.dataset.kind,b.dataset.id,true));document.querySelectorAll(".reqReject").forEach(b=>b.onclick=()=>moderateRequest(b.dataset.kind,b.dataset.id,false))}
function moderateRequest(kind,id,accept){const arr=demoRequests[kind],i=arr.findIndex(r=>r.id===id);if(i<0)return;const q=arr[i];if(!accept){arr.splice(i,1);auditEvent("Відхилено заявку",id);renderRequests();return}if(!window.IIGContacts||!window.IIGContacts.ingestRequest){gate("Модуль єдиної бази ще завантажується. Повторіть дію через секунду.");return}const marketing=kind==="subscribe"&&q.marketingConsent===true;const res=window.IIGContacts.ingestRequest({email:q.email,name:q.name,company:q.company,position:q.position||"",source:"Website form "+id,language:q.language||"UA",marketingConsent:marketing,consentEvidence:marketing?(q.consent+" · Demo evidence"):"",unsubscribe:q.unsubscribe===true,status:q.unsubscribe?"suppressed":""});auditEvent("Схвалено заявку → база контактів",id,res.status||"OK");arr.splice(i,1);renderRequests();gate(marketing?"Контакт додано до єдиної бази як ACTIVE на підставі явної Digest-згоди.":"Контакт додано до єдиної бази як PENDING. Згода на обробку запиту не прирівнюється до згоди на маркетингову розсилку.")}
renderRequests();
loadSources();loadContent();renderAudit();
